    int vowelConsonantScore(string s) {
        string v = "aeiouAEIOU";
        int score = 0;
        for (char ch : s) {
            if (isalpha(ch)) {
                if (v.find(ch) != string::npos) score += 2;
                else score -= 1;
            }
        }
        return score;
    }
};

class Solution {
    public int vowelConsonantScore(String s) {
        String v = "aeiouAEIOU";
        int score = 0;
        for (char ch : s.toCharArray()) {
            if (Character.isLetter(ch)) {
                if (v.indexOf(ch) != -1) score += 2;
                else score -= 1;
            }
        }
        return score;
    }
}

var vowelConsonantScore = function(s) {
    const vowels = new Set('aeiouAEIOU');
    let score = 0;
    for (const ch of s) {
        if (/[a-zA-Z]/.test(ch)) {
            if (vowels.has(ch)) score += 2;
            else score -= 1;
        }
    }
    return score;
};
